insert into recipes
  (id, name, category, cuisine, "cookTime", "prepTime", "totalTime", rating, servings, source, tags, tried, ingredients, instructions, notes)
values
  ('palak-paneer', 'Palak Paneer', ARRAY['Dinner']::text[], 'Indian', 30, 20, 50, null, 4, '', ARRAY['vegetarian']::text[], false, ARRAY['500 g spinach','250 g paneer, cubed','1 onion and 2 tomatoes','Garlic, ginger, cumin, and garam masala','Cream or yogurt, salt, and oil']::text[], ARRAY['Blanch the spinach, cool it, and blend into a smooth purée.','Brown the paneer cubes and set them aside.','Cook the onion, garlic, ginger, tomatoes, and spices.','Add the spinach purée and paneer, then simmer gently and finish with cream or yogurt.']::text[], 'Avoid boiling after adding dairy to keep the sauce smooth.'),
  ('chana-masala', 'Chana Masala', ARRAY['Lunch','Dinner']::text[], 'Indian', 35, 15, 50, null, 4, '', ARRAY['vegetarian','freezer-friendly']::text[], false, ARRAY['2 cans chickpeas','1 onion, 2 tomatoes, and 3 garlic cloves','Ginger, cumin, coriander, and garam masala','Chili, turmeric, and fresh coriander']::text[], ARRAY['Sauté the onion, garlic, and ginger until golden.','Add tomatoes and spices, cooking until thick and fragrant.','Stir in chickpeas and enough water to make a saucy curry.','Simmer until the flavors come together and garnish with coriander.']::text[], 'Serve with rice, roti, or naan.'),
  ('chicken-pad-thai', 'Chicken Pad Thai', ARRAY['Lunch','Dinner']::text[], 'Thai', 15, 20, 35, null, 4, '', ARRAY['quick']::text[], false, ARRAY['300 g rice noodles','400 g chicken breast, sliced','2 eggs and 1 cup bean sprouts','Peanuts, spring onions, and lime','Fish sauce, tamarind paste, sugar, and chili']::text[], ARRAY['Soak the noodles until pliable and mix the sauce.','Stir-fry the chicken, then push it aside and scramble the eggs.','Add noodles and sauce, tossing until coated and tender.','Fold in bean sprouts and spring onions; serve with peanuts and lime.']::text[], 'Keep the wok hot and avoid overcrowding it.'),
  ('thai-green-curry-with-tofu', 'Thai Green Curry with Tofu', ARRAY['Dinner']::text[], 'Thai', 30, 15, 45, null, 4, '', ARRAY['vegetarian']::text[], false, ARRAY['400 g firm tofu','3 tbsp green curry paste','400 ml coconut milk','1 eggplant and 1 bell pepper','Thai basil, lime leaves, and soy sauce']::text[], ARRAY['Brown the tofu and set it aside.','Fry the curry paste briefly, then add coconut milk.','Add the vegetables and simmer until tender.','Return the tofu, season, and finish with Thai basil and lime leaves.']::text[], 'Serve with jasmine rice and fresh lime.'),
  ('fish-vindaye', 'Fish Vindaye', ARRAY['Dinner']::text[], 'Mauritian', 30, 20, 50, null, 4, '', ARRAY['quick']::text[], false, ARRAY['600 g firm white fish','2 onions and 3 garlic cloves','1 tbsp mustard seeds','Turmeric, vinegar, ginger, and chili','Fresh coriander']::text[], ARRAY['Season the fish with turmeric and pan-fry until lightly golden.','Sauté the onions, garlic, ginger, and mustard seeds.','Add vinegar, chili, and a little water, then return the fish to the pan.','Simmer gently and finish with fresh coriander.']::text[], 'Serve with rice and a crisp salad.'),
  ('gateau-piment', 'Gateau Piment', ARRAY['Breakfast','Lunch']::text[], 'Mauritian', 20, 20, 40, null, 6, '', ARRAY['vegetarian','quick']::text[], false, ARRAY['250 g split yellow peas','2 green chilies','1 small onion','Fresh coriander and curry leaves','Cumin, turmeric, salt, and oil']::text[], ARRAY['Soak the split peas, drain, and grind to a coarse paste.','Mix with chilies, onion, herbs, and spices.','Shape into small balls and flatten slightly.','Deep-fry until golden and crisp.']::text[], 'A popular Mauritian snack, especially with chili sauce.'),
  ('margherita-pizza', 'Margherita Pizza', ARRAY['Dinner']::text[], 'Italian', 15, 30, 45, null, 4, '', ARRAY['vegetarian']::text[], false, ARRAY['500 g pizza dough','200 g crushed tomatoes','250 g mozzarella','Fresh basil','Olive oil, salt, and pepper']::text[], ARRAY['Stretch the dough onto a hot baking tray or pizza stone.','Spread with tomatoes and season lightly.','Add mozzarella and bake at the highest oven temperature until blistered.','Finish with basil and olive oil.']::text[], 'Preheat the oven thoroughly for a crisp base.'),
  ('chicken-schnitzel', 'Chicken Schnitzel', ARRAY['Dinner']::text[], 'Continental', 20, 20, 40, null, 4, '', ARRAY['quick']::text[], false, ARRAY['4 chicken breasts','100 g flour','2 eggs','150 g breadcrumbs','Lemon, salt, pepper, and oil']::text[], ARRAY['Flatten the chicken to an even thickness and season.','Coat each piece in flour, egg, and breadcrumbs.','Pan-fry until golden and cooked through.','Serve with lemon and a fresh salad.']::text[], 'Panko breadcrumbs give an extra-crisp coating.'),
  ('shakshuka', 'Shakshuka', ARRAY['Breakfast','Lunch']::text[], 'Mediterranean', 30, 10, 40, null, 4, '', ARRAY['vegetarian']::text[], false, ARRAY['1 onion and 1 red bell pepper','2 garlic cloves','800 g tomatoes','6 eggs','Cumin, paprika, chili, and fresh parsley']::text[], ARRAY['Sauté the onion, pepper, and garlic until soft.','Add tomatoes and spices, then simmer until thickened.','Make wells in the sauce and crack in the eggs.','Cover and cook until the whites are set; garnish with parsley.']::text[], 'Serve with crusty bread for dipping.'),
  ('greek-salad', 'Greek Salad', ARRAY['Lunch']::text[], 'Mediterranean', 0, 15, 15, null, 4, '', ARRAY['vegetarian','quick']::text[], false, ARRAY['3 tomatoes','1 cucumber and 1 red onion','150 g feta cheese','Kalamata olives','Olive oil, lemon juice, oregano, salt, and pepper']::text[], ARRAY['Chop the tomatoes, cucumber, and onion.','Toss with olives and the dressing.','Add feta on top and serve chilled.']::text[], 'Add the dressing just before serving to keep the vegetables crisp.'),
  ('kung-pao-chicken', 'Kung Pao Chicken', ARRAY['Dinner']::text[], 'Chinese', 20, 20, 40, null, 4, '', ARRAY['quick']::text[], true, ARRAY['600 g chicken breast or thigh, cubed','1 bell pepper and 4 spring onions','50 g roasted peanuts','Dried chilies and garlic','Soy sauce, rice vinegar, sugar, and cornstarch']::text[], ARRAY['Toss the chicken with cornstarch and prepare the sauce.','Stir-fry the chicken until browned, then remove it.','Fry the chilies, garlic, pepper, and spring onions briefly.','Return the chicken, add the sauce and peanuts, and toss until glossy.']::text[], 'Adjust the dried chilies to control the heat.'),
  ('chicken-daube-mauricien', 'Chicken Daube Mauricien', ARRAY['Dinner']::text[], 'Mauritian', 75, 20, 95, null, 4, '', ARRAY['freezer-friendly']::text[], false, ARRAY['800 g chicken thighs','2 onions and 3 garlic cloves','400 g tomatoes','2 potatoes','Thyme, bay leaf, ginger, and chili']::text[], ARRAY['Brown the chicken in a heavy pot and set it aside.','Sauté the onions, garlic, ginger, and chili until fragrant.','Add tomatoes, herbs, potatoes, and chicken, then cover and simmer until tender.','Serve hot with rice or bread.']::text[], 'A comforting Mauritian stew that reheats well.'),
  ('vegetable-fried-rice', 'Vegetable Fried Rice', ARRAY['Lunch','Dinner']::text[], 'Chinese', 15, 15, 30, null, 4, '', ARRAY['vegetarian','quick']::text[], false, ARRAY['4 cups cooked, chilled rice','2 eggs','1 cup mixed vegetables','2 spring onions','Soy sauce, sesame oil, and white pepper']::text[], ARRAY['Scramble the eggs in a hot wok and set them aside.','Stir-fry the vegetables until crisp-tender.','Add the rice and sauces, tossing until hot and separate.','Return the eggs, add spring onions, and serve.']::text[], 'Use day-old rice for the best texture.'),
  ('dholl-puri', 'Dholl Puri', ARRAY['Breakfast','Lunch']::text[], 'Mauritian', 30, 45, 75, null, 4, '', ARRAY['vegetarian']::text[], false, ARRAY['250 g split yellow peas','400 g flour','1 onion, finely chopped','1 tomato and fresh coriander','Curry powder, turmeric, salt, and oil']::text[], ARRAY['Cook the split peas with turmeric until tender, then mash with seasoning.','Make a soft dough, fill with the pea mixture, and roll into thin discs.','Cook the discs on a hot griddle with a little oil until lightly browned.','Serve with rougaille or your preferred curry.']::text[], 'A Mauritian street-food classic; prepare the pea filling ahead of time.'),
  ('farata-mauritian-roti', 'Farata (Mauritian roti)', ARRAY['Bread']::text[], 'Mauritian', null, null, 60, null, 4, '', ARRAY['vegetarian']::text[], false, ARRAY['400 g flour','1 tsp baking powder and 1 tsp salt','250 ml warm water','Oil for kneading and cooking']::text[], ARRAY['Mix flour, baking powder, and salt, then knead in warm water to a soft dough.','Rest the dough, then divide into balls and roll out thin, brushing with oil as you fold and re-roll.','Cook each flatbread on a hot, lightly oiled griddle until puffed and lightly browned on both sides.']::text[], ''),
  ('rougaille-saucisse', 'Rougaille saucisse', ARRAY['Main']::text[], 'Mauritian', null, null, 40, null, 4, '', ARRAY['quick','tomato-based']::text[], false, ARRAY['6 chicken sausages, sliced','1 onion and 3 garlic cloves','500 g tomatoes','Thyme, ginger, and chili','Fresh coriander and oil']::text[], ARRAY['Brown the sausages lightly and set them aside.','Sauté the onion and garlic, then add tomatoes, thyme, ginger, and chili.','Simmer until the sauce thickens, return the sausages, and finish with fresh coriander.']::text[], ''),
  ('cari-poulet-chicken-curry', 'Cari poulet (chicken curry)', ARRAY['Main']::text[], 'Mauritian', null, null, 60, null, 4, '', ARRAY['curry']::text[], false, ARRAY['800 g chicken, cut into pieces','2 onions and 4 garlic cloves','2 tomatoes and 2 potatoes','Curry powder, turmeric, and thyme','Ginger, chili, and fresh coriander']::text[], ARRAY['Brown the chicken pieces and set them aside.','Sauté the onions and garlic, then add curry powder, turmeric, and thyme until fragrant.','Add tomatoes, potatoes, and chicken with a little water, then cover and simmer until tender.','Finish with ginger, chili, and fresh coriander.']::text[], ''),
  ('briani', 'Briani', ARRAY['Main']::text[], 'Mauritian', null, null, 120, null, 4, '', ARRAY['festive','rice']::text[], false, ARRAY['800 g chicken or mutton','500 g basmati rice','2 onions, sliced and fried','Potatoes, saffron or food colouring, and ghee','Curry powder, cumin, cardamom, and bay leaf']::text[], ARRAY['Marinate the chicken or mutton in yogurt and spices, then brown and set aside.','Parboil the rice with saffron or food colouring until just undercooked.','Layer the meat, fried onions, and potatoes with the rice in a heavy pot.','Cover tightly and cook on low heat until the rice is fully tender and fragrant.']::text[], ''),
  ('mine-frit', 'Mine frit', ARRAY['Main']::text[], 'Mauritian', null, null, 30, null, 4, '', ARRAY['quick','noodles']::text[], false, ARRAY['400 g egg noodles','200 g chicken or prawns, sliced','2 eggs and 2 spring onions','1 cup shredded cabbage and carrot','Soy sauce, garlic, and oil']::text[], ARRAY['Boil the noodles briefly, drain, and toss with a little oil.','Stir-fry the chicken or prawns until cooked, then push aside and scramble the eggs.','Add the cabbage, carrot, and spring onions, stir-frying until crisp-tender.','Toss in the noodles with soy sauce and garlic until evenly coated and hot.']::text[], ''),
  ('bol-renvers-magic-bowl', 'Bol renversé (magic bowl)', ARRAY['Main']::text[], 'Mauritian', null, null, 40, null, 4, '', ARRAY['rice','Sino-Mauritian']::text[], false, ARRAY['400 g cooked rice','300 g chicken, sliced','1 fried egg per bowl','Sauteed vegetables and achard','Soy sauce, chili, and oil']::text[], ARRAY['Cook the rice and keep it warm.','Stir-fry the chicken with soy sauce, chili, and a little oil.','Sauté the vegetables separately and fry an egg for each bowl.','Layer rice, meat, vegetables, and achard, then top with the fried egg.']::text[], ''),
  ('achard-l-gumes', 'Achard légumes', ARRAY['Side']::text[], 'Mauritian', null, null, 30, null, 4, '', ARRAY['vegetarian','pickle']::text[], false, ARRAY['1 small cabbage, shredded','2 carrots, julienned','1 green papaya or green beans','Mustard seeds, turmeric, and garlic','Vinegar, chili, and oil']::text[], ARRAY['Blanch the cabbage, carrots, and papaya or beans briefly, then drain well.','Toast the mustard seeds and turmeric in oil, then add garlic.','Toss the vegetables with the spiced oil, vinegar, and chili.','Chill before serving so the flavors can develop.']::text[], 'Extra prep: Resting'),
  ('sweet-and-sour-chicken', 'Sweet and sour chicken', ARRAY['Main']::text[], 'Chinese', null, null, 45, null, 4, '', ARRAY['fried']::text[], false, ARRAY['500 g chicken breast, cubed','1 bell pepper and 1 onion','200 g pineapple chunks','Ketchup, vinegar, sugar, and soy sauce','Cornstarch and oil']::text[], ARRAY['Coat the chicken in cornstarch and fry until golden, then set aside.','Stir-fry the onion and pepper briefly.','Add the pineapple and sauce ingredients, simmering until thickened.','Return the chicken and toss until well coated.']::text[], 'Chicken swapped in for pork.'),
  ('mapo-tofu', 'Mapo tofu', ARRAY['Main']::text[], 'Chinese', null, null, 30, null, 4, '', ARRAY['spicy','Sichuan']::text[], false, ARRAY['400 g soft tofu, cubed','150 g minced chicken','2 tbsp doubanjiang (chili bean paste)','Garlic, ginger, and spring onions','Soy sauce, cornstarch, and Sichuan pepper']::text[], ARRAY['Brown the minced chicken with garlic and ginger.','Stir in the doubanjiang and fry briefly until fragrant.','Add the tofu and a little stock, simmering gently so the tofu stays intact.','Thicken with cornstarch slurry and finish with spring onions and Sichuan pepper.']::text[], ''),
  ('egg-fried-rice', 'Egg fried rice', ARRAY['Main']::text[], 'Chinese', null, null, 20, null, 4, '', ARRAY['quick','leftovers']::text[], false, ARRAY['4 cups cooked, chilled rice','2 eggs','2 spring onions and 1 carrot, diced','Soy sauce and sesame oil','Salt and white pepper']::text[], ARRAY['Scramble the eggs in a hot wok and set them aside.','Stir-fry the carrot and spring onions briefly.','Add the rice, breaking up any clumps, and toss until hot.','Return the eggs, season with soy sauce and sesame oil, and serve.']::text[], ''),
  ('chow-mein', 'Chow mein', ARRAY['Main']::text[], 'Chinese', null, null, 25, null, 4, '', ARRAY['quick','noodles']::text[], false, ARRAY['350 g egg noodles','200 g chicken or prawns, sliced','1 cup shredded cabbage and carrot','2 spring onions and 2 garlic cloves','Soy sauce, oyster sauce, and sesame oil']::text[], ARRAY['Boil the noodles until just tender, drain, and toss with a little oil.','Stir-fry the chicken or prawns until cooked, then set aside.','Stir-fry the cabbage, carrot, and garlic briefly.','Add the noodles, meat, and sauces, tossing everything together until hot.']::text[], ''),
  ('chicken-and-cabbage-dumplings-jiaozi', 'Chicken and cabbage dumplings (jiaozi)', ARRAY['Snack']::text[], 'Chinese', null, null, 90, null, 4, '', ARRAY['freezer-friendly']::text[], false, ARRAY['300 g minced chicken','200 g cabbage, finely chopped and salted','2 spring onions and 2 garlic cloves','Dumpling wrappers','Soy sauce, ginger, and sesame oil']::text[], ARRAY['Mix the minced chicken with the salted, squeezed cabbage, spring onions, garlic, and seasoning.','Place a spoonful of filling in each wrapper and fold into dumplings.','Boil or steam the dumplings until the filling is cooked through.','Serve with a soy and sesame oil dipping sauce.']::text[], 'Chicken swapped in for pork.'),
  ('hot-and-sour-soup', 'Hot and sour soup', ARRAY['Soup']::text[], 'Chinese', null, null, 30, null, 4, '', ARRAY['spicy']::text[], false, ARRAY['1 L chicken or vegetable stock','150 g tofu, sliced','50 g mushrooms and 1 egg','Vinegar, white pepper, and chili oil','Soy sauce and cornstarch']::text[], ARRAY['Bring the stock to a simmer and add the mushrooms and tofu.','Season with soy sauce, vinegar, and white pepper.','Thicken lightly with cornstarch slurry, then swirl in the beaten egg.','Finish with chili oil just before serving.']::text[], ''),
  ('char-siu-bbq-chicken', 'Char siu (BBQ chicken)', ARRAY['Main']::text[], 'Chinese', null, null, 60, null, 4, '', ARRAY['roasted']::text[], false, ARRAY['600 g chicken thighs','2 tbsp hoisin sauce and 1 tbsp honey','Soy sauce and Chinese five-spice','Garlic and ginger','Red food colouring (optional)']::text[], ARRAY['Mix the hoisin, honey, soy sauce, five-spice, garlic, and ginger into a marinade.','Marinate the chicken thighs for at least a few hours, or overnight.','Roast or grill, basting with the marinade, until caramelized and cooked through.','Rest briefly before slicing.']::text[], 'Extra prep: Marinating. Chicken swapped in for pork.'),
  ('steamed-fish-with-ginger-and-scallion', 'Steamed fish with ginger and scallion', ARRAY['Main']::text[], 'Chinese', null, null, 25, null, 4, '', ARRAY['seafood','healthy']::text[], false, ARRAY['1 whole white fish or 2 fillets','3 slices ginger and 2 spring onions, julienned','Soy sauce and Shaoxing wine','Sesame oil','Salt and white pepper']::text[], ARRAY['Place the fish on a plate with ginger and season lightly.','Steam until just cooked through.','Scatter spring onions over the hot fish and drizzle with soy sauce and sesame oil.','Pour a little hot oil over the top to release the aromatics, then serve.']::text[], ''),
  ('spring-rolls', 'Spring rolls', ARRAY['Snack']::text[], 'Chinese', null, null, 60, null, 4, '', ARRAY['fried','party']::text[], false, ARRAY['12 spring roll wrappers','150 g minced chicken or prawns','1 cup shredded cabbage and carrot','Glass noodles and spring onions','Soy sauce and oil for frying']::text[], ARRAY['Stir-fry the minced chicken or prawns with the cabbage, carrot, and glass noodles, seasoning with soy sauce.','Cool the filling, then roll portions in the wrappers, sealing the edges.','Fry the rolls in hot oil until golden and crisp.','Drain and serve with a dipping sauce.']::text[], ''),
  ('hummus', 'Hummus', ARRAY['Snack']::text[], 'Mediterranean', null, null, 15, null, 4, '', ARRAY['vegan','dip']::text[], false, ARRAY['2 cans chickpeas','3 tbsp tahini','2 garlic cloves and juice of 1 lemon','Olive oil and cumin','Salt and paprika, to serve']::text[], ARRAY['Blend the chickpeas, tahini, garlic, and lemon juice until smooth.','Add olive oil and cumin, blending to a creamy consistency, adjusting with water as needed.','Season with salt and transfer to a bowl.','Drizzle with olive oil and dust with paprika before serving.']::text[], ''),
  ('falafel', 'Falafel', ARRAY['Main']::text[], 'Mediterranean', null, null, 45, null, 4, '', ARRAY['vegan','fried']::text[], false, ARRAY['2 cans chickpeas','1 onion and 3 garlic cloves','Fresh parsley and coriander','Cumin, coriander, and baking powder','Flour, salt, and oil for frying']::text[], ARRAY['Blend the chickpeas, onion, garlic, parsley, and coriander with the spices until coarsely ground.','Mix in flour and baking powder, then rest the mixture briefly.','Shape into small balls or patties.','Fry until deep golden and crisp, then drain and serve.']::text[], 'Extra prep: Overnight soak'),
  ('moussaka', 'Moussaka', ARRAY['Main']::text[], 'Mediterranean', null, null, 120, null, 4, '', ARRAY['baked','comfort']::text[], false, ARRAY['2 eggplants, sliced','500 g minced lamb','1 onion, 2 garlic cloves, and 2 tomatoes','500 ml bechamel sauce','Cinnamon, oregano, and olive oil']::text[], ARRAY['Salt the eggplant slices, then fry or roast until golden.','Cook the onion and garlic, add the minced meat, and brown well, then stir in tomatoes and cinnamon.','Make the bechamel sauce until thick and smooth.','Layer eggplant and meat sauce in a dish, top with bechamel, and bake until golden and set.']::text[], ''),
  ('tabbouleh', 'Tabbouleh', ARRAY['Side']::text[], 'Mediterranean', null, null, 20, null, 4, '', ARRAY['vegan','healthy']::text[], false, ARRAY['100 g fine bulgur','2 bunches fresh parsley, finely chopped','3 tomatoes and 4 spring onions','Fresh mint','Olive oil, lemon juice, salt, and pepper']::text[], ARRAY['Soak the bulgur in water until tender, then drain well.','Finely chop the parsley, mint, tomatoes, and spring onions.','Toss everything with the bulgur, olive oil, and lemon juice.','Season with salt and pepper and chill before serving.']::text[], ''),
  ('chicken-souvlaki', 'Chicken souvlaki', ARRAY['Main']::text[], 'Mediterranean', null, null, 30, null, 4, '', ARRAY['grilled']::text[], false, ARRAY['600 g chicken breast, cubed','2 garlic cloves and juice of 1 lemon','Oregano and olive oil','Pita bread, to serve','Salt and pepper']::text[], ARRAY['Marinate the chicken cubes in garlic, lemon juice, oregano, and olive oil.','Thread onto skewers.','Grill or pan-fry, turning occasionally, until charred and cooked through.','Serve with pita bread.']::text[], 'Extra prep: Marinating'),
  ('spanakopita', 'Spanakopita', ARRAY['Main']::text[], 'Mediterranean', null, null, 75, null, 4, '', ARRAY['vegetarian','baked']::text[], false, ARRAY['500 g spinach','200 g feta cheese','1 onion and 2 spring onions','250 g phyllo pastry','Dill, egg, olive oil, salt, and pepper']::text[], ARRAY['Wilt the spinach, cool, and squeeze out excess liquid, then mix with feta, onion, dill, and egg.','Layer sheets of phyllo in a baking dish, brushing each with olive oil.','Spread the spinach filling over the phyllo, then top with more buttered or oiled phyllo sheets.','Score the top and bake until golden and crisp.']::text[], ''),
  ('seafood-paella', 'Seafood paella', ARRAY['Main']::text[], 'Mediterranean', null, null, 60, null, 4, '', ARRAY['seafood','rice']::text[], false, ARRAY['300 g paella rice','400 g mixed seafood (prawns, mussels, squid)','1 onion, 1 bell pepper, and 3 garlic cloves','2 tomatoes and saffron','Fish stock, olive oil, salt, and pepper']::text[], ARRAY['Sauté the onion, pepper, and garlic in olive oil, then add tomatoes and saffron.','Stir in the rice, coating it in the sofrito.','Add hot fish stock and simmer without stirring until the rice is nearly tender.','Arrange the seafood over the rice, cover, and cook until everything is tender.']::text[], ''),
  ('baklava', 'Baklava', ARRAY['Dessert']::text[], 'Mediterranean', null, null, 90, null, 4, '', ARRAY['festive','nuts']::text[], false, ARRAY['250 g phyllo pastry','200 g mixed nuts (walnuts, pistachios), chopped','150 g melted butter','Sugar syrup','Cinnamon and lemon juice']::text[], ARRAY['Layer sheets of phyllo in a baking dish, brushing each with melted butter.','Scatter the chopped nuts over the middle layers.','Cut into pieces before baking, then bake until golden and crisp.','Pour the sugar syrup over the hot baklava and let it soak in before serving.']::text[], ''),
  ('herb-roast-chicken', 'Herb roast chicken', ARRAY['Main']::text[], 'Continental', null, null, 90, null, 4, '', ARRAY['Sunday roast']::text[], false, ARRAY['1 whole chicken','Thyme, rosemary, and garlic','1 lemon','Butter or olive oil','Salt and pepper']::text[], ARRAY['Rub the chicken all over with butter or oil, garlic, herbs, salt, and pepper.','Stuff the cavity with the lemon.','Roast until the skin is golden and the juices run clear.','Rest before carving.']::text[], ''),
  ('chicken-stroganoff', 'Chicken stroganoff', ARRAY['Main']::text[], 'Continental', null, null, 40, null, 4, '', ARRAY['creamy']::text[], false, ARRAY['600 g chicken breast, sliced','1 onion and 200 g mushrooms','250 ml sour cream','Chicken stock and mustard','Salt, pepper, and oil']::text[], ARRAY['Brown the chicken slices and set them aside.','Sauté the onion and mushrooms until golden.','Add stock and mustard, then return the chicken and simmer.','Stir in the sour cream and season before serving.']::text[], 'Chicken swapped in for beef.'),
  ('french-onion-soup', 'French onion soup', ARRAY['Soup']::text[], 'Continental', null, null, 75, null, 4, '', ARRAY['comfort']::text[], false, ARRAY['4 large onions, sliced','1 L vegetable or chicken stock','Baguette slices','Gruyere cheese','Butter, thyme, salt, and pepper']::text[], ARRAY['Cook the onions slowly in butter until deeply caramelized.','Add the stock and thyme, then simmer until the flavors meld.','Ladle into bowls, top with baguette slices and cheese.','Broil until the cheese is bubbling and golden.']::text[], ''),
  ('chicken-cordon-bleu', 'Chicken cordon bleu', ARRAY['Main']::text[], 'Continental', null, null, 60, null, 4, '', ARRAY['baked']::text[], false, ARRAY['4 chicken breasts','4 slices turkey ham and 4 slices Swiss cheese','100 g flour and 2 eggs','150 g breadcrumbs','Salt, pepper, and oil']::text[], ARRAY['Flatten the chicken breasts and top each with a slice of turkey ham and cheese, then roll or fold closed.','Coat in flour, egg, and breadcrumbs.','Pan-fry or bake until golden and cooked through.','Rest briefly before serving.']::text[], ''),
  ('coq-au-vin', 'Coq au vin', ARRAY['Main']::text[], 'Continental', null, null, 150, null, 4, '', ARRAY['slow-cooked']::text[], false, ARRAY['1 whole chicken, cut into pieces','750 ml red wine','150 g turkey bacon, diced','1 onion, carrots, and mushrooms','Garlic, thyme, bay leaf, and butter']::text[], ARRAY['Brown the chicken pieces and turkey bacon, then set aside.','Sauté the onion, carrots, and mushrooms.','Add the wine, garlic, thyme, and bay leaf, then return the chicken and turkey bacon.','Cover and simmer until the chicken is tender and the sauce has reduced.']::text[], 'Chicken braised in red wine — swapped in for beef bourguignon.'),
  ('quiche-lorraine', 'Quiche Lorraine', ARRAY['Main']::text[], 'Continental', null, null, 75, null, 4, '', ARRAY['baked','eggs']::text[], false, ARRAY['1 pastry base','150 g turkey bacon, diced','3 eggs and 250 ml cream','100 g grated cheese','Salt, pepper, and nutmeg']::text[], ARRAY['Blind-bake the pastry base until lightly golden.','Scatter the turkey bacon and cheese over the base.','Whisk the eggs with cream, salt, pepper, and nutmeg, then pour over the filling.','Bake until the filling is set and golden.']::text[], ''),
  ('caesar-salad', 'Caesar salad', ARRAY['Side']::text[], 'Continental', null, null, 20, null, 4, '', ARRAY['quick']::text[], false, ARRAY['1 romaine lettuce','4 chicken breast, grilled','50 g parmesan and croutons','2 anchovy fillets and 1 garlic clove','Mayonnaise, lemon juice, mustard, and olive oil']::text[], ARRAY['Grill the chicken breasts and slice once cooked.','Blend the anchovies, garlic, mustard, lemon juice, and mayonnaise into a dressing.','Toss the romaine lettuce with the dressing.','Top with sliced chicken, croutons, and parmesan.']::text[], ''),
  ('fish-and-chips', 'Fish and chips', ARRAY['Main']::text[], 'Continental', null, null, 45, null, 4, '', ARRAY['seafood','fried']::text[], false, ARRAY['4 white fish fillets','150 g flour and cold sparkling water or beer','4 potatoes, cut into chips','Baking powder','Salt, pepper, and oil for frying']::text[], ARRAY['Cut the potatoes into chips and fry or cook until golden and crisp.','Whisk the flour with sparkling water or beer and baking powder into a batter.','Dip the fish in the batter and fry until golden and cooked through.','Drain and serve the fish and chips together with salt.']::text[], ''),
  ('creamy-mashed-potatoes', 'Creamy mashed potatoes', ARRAY['Side']::text[], 'Continental', null, null, 30, null, 4, '', ARRAY['vegetarian']::text[], false, ARRAY['1 kg potatoes','100 g butter','150 ml milk or cream','Salt and white pepper','Nutmeg (optional)']::text[], ARRAY['Boil the potatoes until tender, then drain well.','Mash while hot, or pass through a ricer.','Beat in the butter and warm milk or cream until smooth.','Season with salt, white pepper, and nutmeg.']::text[], ''),
  ('cr-me-br-l-e', 'Crème brûlée', ARRAY['Dessert']::text[], 'Continental', null, null, 60, null, 4, '', ARRAY['make-ahead']::text[], false, ARRAY['500 ml cream','1 vanilla pod or vanilla extract','5 egg yolks','100 g sugar, plus extra for the brulee topping','A pinch of salt']::text[], ARRAY['Warm the cream with the vanilla.','Whisk the egg yolks with sugar, then slowly pour in the warm cream, whisking constantly.','Strain into ramekins and bake in a water bath until just set.','Chill, then sprinkle sugar on top and caramelize with a torch or under the broiler before serving.']::text[], 'Extra prep: Chilling'),
  ('spaghetti-carbonara', 'Spaghetti carbonara', ARRAY['Main']::text[], 'Italian', null, null, 25, null, 4, '', ARRAY['quick','pasta']::text[], false, ARRAY['400 g spaghetti','150 g turkey bacon, diced','3 eggs and 50 g grated parmesan','2 garlic cloves','Black pepper and salt']::text[], ARRAY['Cook the spaghetti in salted water until al dente.','Render the turkey bacon with garlic until crisp.','Whisk the eggs with the parmesan and black pepper.','Off the heat, toss the hot pasta with the turkey bacon, then quickly mix in the egg mixture until creamy.']::text[], ''),
  ('lasagna', 'Lasagna', ARRAY['Main']::text[], 'Italian', null, null, 120, null, 4, '', ARRAY['baked','freezer-friendly']::text[], false, ARRAY['250 g lasagna sheets','500 g minced chicken or turkey','1 onion, 2 garlic cloves, and 400 g tomatoes','500 ml bechamel sauce','100 g grated parmesan or mozzarella']::text[], ARRAY['Brown the minced chicken or turkey with onion and garlic, then add tomatoes and simmer into a ragu.','Make the bechamel sauce until smooth.','Layer lasagna sheets, ragu, and bechamel in a baking dish, repeating until the dish is full.','Top with cheese and bake until golden and bubbling.']::text[], ''),
  ('mushroom-risotto', 'Mushroom risotto', ARRAY['Main']::text[], 'Italian', null, null, 45, null, 4, '', ARRAY['vegetarian','rice']::text[], false, ARRAY['300 g arborio rice','400 g mixed mushrooms, sliced','1 onion and 2 garlic cloves','1 L vegetable or chicken stock','White wine, parmesan, and butter']::text[], ARRAY['Sauté the mushrooms until golden and set aside.','Cook the onion and garlic in butter, then add the rice and toast briefly.','Add the wine, then gradually add hot stock, stirring until each addition is absorbed.','Stir in the mushrooms, parmesan, and butter, and serve immediately.']::text[], ''),
  ('penne-arrabbiata', 'Penne arrabbiata', ARRAY['Main']::text[], 'Italian', null, null, 25, null, 4, '', ARRAY['vegan','spicy','quick']::text[], false, ARRAY['400 g penne','400 g tomatoes','3 garlic cloves and 1-2 dried chilies','Fresh parsley','Olive oil and salt']::text[], ARRAY['Cook the penne in salted water until al dente.','Gently fry the garlic and chilies in olive oil, then add the tomatoes.','Simmer the sauce until thickened, seasoning with salt.','Toss the pasta with the sauce and finish with fresh parsley.']::text[], ''),
  ('minestrone', 'Minestrone', ARRAY['Soup']::text[], 'Italian', null, null, 60, null, 4, '', ARRAY['vegetarian','healthy']::text[], false, ARRAY['1 onion, 2 carrots, and 2 celery stalks','400 g tomatoes and 1 can beans','100 g pasta or rice','1 L vegetable stock','Garlic, basil, olive oil, salt, and pepper']::text[], ARRAY['Sauté the onion, carrots, and celery in olive oil with garlic.','Add the tomatoes, beans, and stock, then simmer.','Add the pasta or rice and cook until tender.','Finish with basil, salt, and pepper before serving.']::text[], ''),
  ('bruschetta', 'Bruschetta', ARRAY['Snack']::text[], 'Italian', null, null, 15, null, 4, '', ARRAY['vegan','quick']::text[], false, ARRAY['1 baguette or ciabatta, sliced','4 tomatoes, diced','2 garlic cloves','Fresh basil','Olive oil, salt, and pepper']::text[], ARRAY['Toast or grill the bread slices until golden.','Mix the diced tomatoes with garlic, basil, olive oil, salt, and pepper.','Spoon the tomato mixture over the toasted bread.','Serve immediately while the bread is still crisp.']::text[], ''),
  ('chicken-parmigiana', 'Chicken parmigiana', ARRAY['Main']::text[], 'Italian', null, null, 60, null, 4, '', ARRAY['baked']::text[], false, ARRAY['4 chicken breasts','100 g flour, 2 eggs, and 150 g breadcrumbs','400 g tomato sauce','200 g mozzarella and grated parmesan','Fresh basil, salt, and pepper']::text[], ARRAY['Coat the chicken breasts in flour, egg, and breadcrumbs.','Fry until golden and cooked through.','Top with tomato sauce and mozzarella.','Bake until the cheese is melted and bubbling, then finish with basil.']::text[], ''),
  ('osso-buco', 'Osso buco', ARRAY['Main']::text[], 'Italian', null, null, 150, null, 4, '', ARRAY['slow-cooked']::text[], false, ARRAY['4 lamb shanks','1 onion, 2 carrots, and 2 celery stalks','400 g tomatoes and 250 ml white wine','Chicken stock','Garlic, lemon zest, and fresh parsley (gremolata)']::text[], ARRAY['Dust the lamb shanks with flour and brown well, then set aside.','Sauté the onion, carrots, celery, and garlic.','Add the wine, tomatoes, and stock, then return the shanks.','Cover and simmer until the meat is tender, then finish with gremolata.']::text[], ''),
  ('tiramisu', 'Tiramisu', ARRAY['Dessert']::text[], 'Italian', null, null, 30, null, 4, '', ARRAY['no-bake','make-ahead']::text[], false, ARRAY['250 g mascarpone','3 eggs, separated','100 g sugar','200 g ladyfinger biscuits','Strong coffee and cocoa powder']::text[], ARRAY['Whisk the egg yolks with sugar until pale, then beat in the mascarpone.','Whip the egg whites to soft peaks and fold into the mascarpone mixture.','Dip the ladyfingers briefly in coffee and layer with the mascarpone mixture.','Chill for several hours, then dust with cocoa powder before serving.']::text[], 'Extra prep: Chilling'),
  ('pad-thai', 'Pad Thai', ARRAY['Main']::text[], 'Thai', null, null, 30, null, 4, '', ARRAY['noodles']::text[], false, ARRAY['250 g rice noodles','200 g chicken or prawns','2 eggs and 1 cup bean sprouts','Peanuts, spring onions, and lime','Fish sauce, tamarind paste, sugar, and chili flakes']::text[], ARRAY['Soak the rice noodles until pliable and mix the sauce.','Stir-fry the chicken or prawns, then push aside and scramble the eggs.','Add the noodles and sauce, tossing until coated and tender.','Fold in bean sprouts and spring onions, then serve with peanuts and lime.']::text[], ''),
  ('green-curry', 'Green curry', ARRAY['Main']::text[], 'Thai', null, null, 40, null, 4, '', ARRAY['curry','spicy']::text[], false, ARRAY['500 g chicken, sliced','3 tbsp green curry paste','400 ml coconut milk','1 eggplant and 1 bell pepper','Thai basil, fish sauce, and lime leaves']::text[], ARRAY['Fry the curry paste briefly in a little coconut milk until fragrant.','Add the chicken and cook until nearly done.','Add the remaining coconut milk and the vegetables, simmering until tender.','Season with fish sauce and finish with Thai basil and lime leaves.']::text[], ''),
  ('red-curry', 'Red curry', ARRAY['Main']::text[], 'Thai', null, null, 40, null, 4, '', ARRAY['curry']::text[], false, ARRAY['500 g chicken, sliced','3 tbsp red curry paste','400 ml coconut milk','1 bell pepper and bamboo shoots','Thai basil, fish sauce, and lime leaves']::text[], ARRAY['Fry the curry paste briefly in a little coconut milk until fragrant.','Add the meat and cook until nearly done.','Add the remaining coconut milk, bell pepper, and bamboo shoots, simmering until tender.','Season with fish sauce and finish with Thai basil and lime leaves.']::text[], ''),
  ('massaman-curry', 'Massaman curry', ARRAY['Main']::text[], 'Thai', null, null, 90, null, 4, '', ARRAY['curry','mild']::text[], false, ARRAY['600 g chicken, cubed','3 tbsp massaman curry paste','400 ml coconut milk','2 potatoes and 1 onion','Roasted peanuts, tamarind paste, and palm sugar']::text[], ARRAY['Brown the chicken, then set aside.','Fry the curry paste in a little coconut milk until fragrant.','Add the chicken, remaining coconut milk, potatoes, and onion, then simmer until tender.','Stir in peanuts, tamarind paste, and palm sugar before serving.']::text[], ''),
  ('tom-yum-goong', 'Tom yum goong', ARRAY['Soup']::text[], 'Thai', null, null, 30, null, 4, '', ARRAY['seafood','spicy']::text[], false, ARRAY['400 g prawns','1 L stock and 400 ml coconut milk (optional)','Lemongrass, galangal, and lime leaves','100 g mushrooms and 2 tomatoes','Fish sauce, lime juice, and chili']::text[], ARRAY['Bring the stock to a boil with lemongrass, galangal, and lime leaves.','Add the mushrooms and tomatoes, simmering briefly.','Add the prawns and cook until just pink.','Season with fish sauce, lime juice, and chili off the heat.']::text[], ''),
  ('tom-kha-gai', 'Tom kha gai', ARRAY['Soup']::text[], 'Thai', null, null, 35, null, 4, '', ARRAY['coconut']::text[], false, ARRAY['500 g chicken, sliced','400 ml coconut milk','Lemongrass, galangal, and lime leaves','100 g mushrooms','Fish sauce, lime juice, and chili']::text[], ARRAY['Bring the coconut milk to a simmer with lemongrass, galangal, and lime leaves.','Add the chicken and simmer until cooked through.','Add the mushrooms and cook briefly.','Season with fish sauce, lime juice, and chili before serving.']::text[], ''),
  ('pad-kra-pao-holy-basil-stir-fry', 'Pad kra pao (holy basil stir-fry)', ARRAY['Main']::text[], 'Thai', null, null, 20, null, 4, '', ARRAY['quick','spicy']::text[], false, ARRAY['400 g minced chicken','4 garlic cloves and 3-4 chilies','1 cup Thai holy basil leaves','Fish sauce, soy sauce, and sugar','1 fried egg per serving']::text[], ARRAY['Pound or mince the garlic and chilies together.','Stir-fry the minced chicken with the garlic and chilies until cooked.','Season with fish sauce, soy sauce, and sugar, then stir in the holy basil until wilted.','Serve over rice topped with a fried egg.']::text[], ''),
  ('khao-pad-thai-fried-rice', 'Khao pad (Thai fried rice)', ARRAY['Main']::text[], 'Thai', null, null, 20, null, 4, '', ARRAY['quick','leftovers']::text[], false, ARRAY['4 cups cooked, chilled rice','200 g chicken or prawns','1 egg and 1 onion','Fish sauce and soy sauce','Lime and cucumber, to serve']::text[], ARRAY['Stir-fry the chicken or prawns with the onion until cooked.','Push aside and scramble the egg.','Add the rice, breaking up clumps, and season with fish sauce and soy sauce.','Toss until hot and serve with lime and cucumber.']::text[], ''),
  ('som-tam-papaya-salad', 'Som tam (papaya salad)', ARRAY['Side']::text[], 'Thai', null, null, 20, null, 4, '', ARRAY['healthy','spicy']::text[], false, ARRAY['1 green papaya, shredded','2 tomatoes and 2 green beans','2 garlic cloves and 2-3 chilies','Roasted peanuts and dried shrimp','Fish sauce, lime juice, and palm sugar']::text[], ARRAY['Pound the garlic and chilies in a mortar, then add the green beans.','Add the shredded papaya and tomatoes, lightly bruising to release the flavors.','Season with fish sauce, lime juice, and palm sugar, tossing well.','Top with roasted peanuts and dried shrimp before serving.']::text[], ''),
  ('mango-sticky-rice', 'Mango sticky rice', ARRAY['Dessert']::text[], 'Thai', null, null, 45, null, 4, '', ARRAY['vegan']::text[], false, ARRAY['300 g glutinous rice','400 ml coconut milk','2 ripe mangoes, sliced','Sugar and a pinch of salt','Toasted sesame seeds, to serve']::text[], ARRAY['Soak the glutinous rice, then steam until tender.','Warm the coconut milk with sugar and a pinch of salt.','Stir most of the coconut mixture into the hot rice and let it absorb.','Serve the rice with sliced mango, the remaining coconut sauce, and toasted sesame seeds.']::text[], 'Extra prep: Soak'),
  ('butter-chicken', 'Butter chicken', ARRAY['Main']::text[], 'Indian', null, null, 60, null, 4, '', ARRAY['curry','creamy']::text[], false, ARRAY['600 g chicken thighs','1 onion, 3 garlic cloves, and ginger','400 g tomatoes and 150 ml cream','Garam masala, cumin, and paprika','Butter and fresh coriander']::text[], ARRAY['Marinate the chicken in some of the spices and yogurt, if time allows, then brown and set aside.','Sauté the onion, garlic, and ginger, then add the tomatoes and spices.','Simmer the sauce until thickened, then blend smooth if desired.','Return the chicken, stir in the cream and butter, and finish with fresh coriander.']::text[], 'Extra prep: Marinating'),
  ('chicken-biryani', 'Chicken biryani', ARRAY['Main']::text[], 'Indian', null, null, 120, null, 4, '', ARRAY['festive','rice']::text[], false, ARRAY['600 g chicken, cut into pieces','500 g basmati rice','2 onions, fried','Yogurt, saffron, and ghee','Garam masala, cumin, cardamom, and bay leaf']::text[], ARRAY['Marinate the chicken in yogurt and spices, then brown and set aside.','Parboil the rice with whole spices until just undercooked.','Layer the chicken, fried onions, and rice in a heavy pot with saffron and ghee.','Cover tightly and cook on low heat until the rice is fully tender and fragrant.']::text[], ''),
  ('dal-tadka', 'Dal tadka', ARRAY['Main']::text[], 'Indian', null, null, 45, null, 4, '', ARRAY['vegetarian','lentils']::text[], false, ARRAY['250 g split lentils (toor or masoor dal)','1 onion, 3 garlic cloves, and ginger','2 tomatoes','Cumin, turmeric, and chili','Ghee or oil and fresh coriander']::text[], ARRAY['Boil the lentils with turmeric until soft, then set aside.','Sauté the onion, garlic, and ginger, then add tomatoes and spices.','Stir the tempering into the cooked lentils and simmer briefly.','Finish with ghee and fresh coriander.']::text[], ''),
  ('aloo-gobi', 'Aloo gobi', ARRAY['Side']::text[], 'Indian', null, null, 35, null, 4, '', ARRAY['vegan']::text[], false, ARRAY['3 potatoes, cubed','1 small cauliflower, cut into florets','1 onion and 2 tomatoes','Turmeric, cumin, and coriander powder','Ginger, chili, and fresh coriander']::text[], ARRAY['Sauté the onion until soft, then add turmeric, cumin, and coriander powder.','Add the potatoes and cauliflower, stirring to coat in the spices.','Add the tomatoes and a little water, then cover and cook until the vegetables are tender.','Finish with ginger, chili, and fresh coriander.']::text[], ''),
  ('rogan-josh', 'Rogan josh', ARRAY['Main']::text[], 'Indian', null, null, 105, null, 4, '', ARRAY['lamb','slow-cooked']::text[], false, ARRAY['800 g lamb, cubed','2 onions and 4 garlic cloves','Yogurt and ginger','Kashmiri chili powder, cumin, and coriander','Bay leaf, cardamom, and ghee']::text[], ARRAY['Brown the lamb in batches and set aside.','Sauté the onions and garlic until deeply golden.','Add the yogurt, ginger, and spices, then return the lamb with a little water.','Cover and simmer until the lamb is tender and the sauce has thickened.']::text[], ''),
  ('garlic-naan', 'Garlic naan', ARRAY['Bread']::text[], 'Indian', null, null, 90, null, 4, '', ARRAY['vegetarian']::text[], false, ARRAY['400 g flour','1 tsp yeast and 1 tsp sugar','150 ml warm milk and 100 g yogurt','Garlic, crushed','Butter and salt']::text[], ARRAY['Mix the flour, yeast, sugar, and salt, then knead in warm milk and yogurt to a soft dough.','Let the dough rise until puffy.','Divide, roll out, and cook on a very hot griddle or under a broiler until puffed and charred in spots.','Brush with garlic butter immediately after cooking.']::text[], 'Extra prep: Includes rising'),
  ('samosas', 'Samosas', ARRAY['Snack']::text[], 'Indian', null, null, 75, null, 4, '', ARRAY['vegetarian','fried']::text[], false, ARRAY['300 g flour','3 potatoes and 100 g peas','Cumin, coriander, and garam masala','Ginger, chili, and fresh coriander','Oil for dough and frying']::text[], ARRAY['Make a firm dough with the flour and rest it.','Cook the potatoes and peas with the spices, ginger, and chili, then cool.','Roll out the dough, cut and shape into cones, and fill with the potato mixture.','Seal the edges and deep-fry until golden and crisp.']::text[], ''),
  ('gulab-jamun', 'Gulab jamun', ARRAY['Dessert']::text[], 'Indian', null, null, 60, null, 4, '', ARRAY['festive','sweet']::text[], false, ARRAY['250 g milk powder','50 g flour and a pinch of baking soda','Milk, to form the dough','400 g sugar and water, for the syrup','Cardamom and rosewater','Oil or ghee for frying']::text[], ARRAY['Mix the milk powder, flour, and baking soda, adding milk gradually to form a soft dough.','Shape into small smooth balls.','Make a sugar syrup with water, cardamom, and rosewater, and keep it warm.','Fry the balls on low heat until evenly golden, then soak in the warm syrup before serving.']::text[], '')
